### 2. Module 1: Fleet Telemetry Tracker

```csharp
// Modules/FleetTracker/FleetTracker.cs
using System.Collections.Concurrent;
using System.Threading.Channels;

public class FleetTracker : IDisposable
{
    private readonly Channel<TelemetryData> _telemetryChannel;
    private readonly ConcurrentDictionary<string, VehicleState> _vehicleStates;
    private readonly object _lock = new();
    private readonly ILogger<FleetTracker> _logger;
    private readonly IRouteOptimizationService _routeOptimizer;
    private readonly IBillingService _billingService;
    private readonly CancellationTokenSource _cts = new();

    public FleetTracker(
        Channel<TelemetryData> telemetryChannel,
        IRouteOptimizationService routeOptimizer,
        IBillingService billingService,
        ILogger<FleetTracker> logger)
    {
        _telemetryChannel = telemetryChannel;
        _routeOptimizer = routeOptimizer;
        _billingService = billingService;
        _logger = logger;
        _vehicleStates = new ConcurrentDictionary<string, VehicleState>();
    }

    public async Task StartTrackingAsync()
    {
        await foreach (var telemetry in _telemetryChannel.Reader.ReadAllAsync(_cts.Token))
        {
            try
            {
                ProcessTelemetry(telemetry);
                await CheckForAnomalies(telemetry);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing telemetry for vehicle {VehicleId}", telemetry.VehicleId);
            }
        }
    }

    private void ProcessTelemetry(TelemetryData data)
    {
        var currentState = _vehicleStates.GetOrAdd(data.VehicleId, _ => new VehicleState());

        lock (_lock)
        {
            currentState.Update(data);

            // Update route progress if we have a current route
            if (currentState.CurrentRoute != null)
            {
                UpdateRouteProgress(currentState, data);
            }
        }

        // Notify other modules about significant state changes
        if (data.IsMoving && !currentState.PreviousState.IsMoving)
        {
            _logger.LogInformation("Vehicle {VehicleId} started moving", data.VehicleId);
        }
        else if (!data.IsMoving && currentState.PreviousState.IsMoving)
        {
            _logger.LogInformation("Vehicle {VehicleId} stopped moving", data.VehicleId);
        }
    }

    private async Task CheckForAnomalies(TelemetryData data)
    {
        var currentState = _vehicleStates[data.VehicleId];

        // Check for speed anomalies
        if (data.Speed > 120) // Example threshold
        {
            _logger.LogWarning("Speed anomaly detected for vehicle {VehicleId}: {Speed} km/h", data.VehicleId, data.Speed);
            await _routeOptimizer.UpdateTrafficConditions(data.VehicleId, data.Latitude, data.Longitude, 1.5); // Increase traffic weight
        }

        // Check for sudden stops
        if (currentState.PreviousState.Speed > 30 && data.Speed < 5)
        {
            _logger.LogWarning("Sudden stop detected for vehicle {VehicleId}", data.VehicleId);
        }
    }

    private void UpdateRouteProgress(VehicleState state, TelemetryData data)
    {
        // Simple progress calculation - in a real system this would be more sophisticated
        double progress = 0;
        double totalDistance = state.CurrentRoute.TotalDistance;

        if (totalDistance > 0)
        {
            progress = state.DistanceTraveled / totalDistance;
        }

        state.Progress = progress;

        // If we've completed the route, notify billing system
        if (progress >= 1.0 && state.CurrentRoute != null)
        {
            _logger.LogInformation("Vehicle {VehicleId} completed route {RouteId}", data.VehicleId, state.CurrentRoute.GeneratedAt);
            await _billingService.ProcessCompletedRoute(state.CurrentRoute);
            state.CurrentRoute = null;
        }
    }

    public void AssignRouteToVehicle(string vehicleId, RoutePlan routePlan)
    {
        var state = _vehicleStates.GetOrAdd(vehicleId, _ => new VehicleState());
        state.CurrentRoute = routePlan;
    }

    public VehicleState GetVehicleState(string vehicleId)
    {
        _vehicleStates.TryGetValue(vehicleId, out var state);
        return state;
    }

    public void Dispose()
    {
        _cts.Cancel();
        _telemetryChannel.Reader.Complete();
    }

    private class VehicleState
    {
        public TelemetryData PreviousState { get; set; }
        public double DistanceTraveled { get; set; }
        public double Progress { get; set; }
        public RoutePlan CurrentRoute { get; set; }

        public void Update(TelemetryData data)
        {
            PreviousState = new TelemetryData
            {
                Timestamp = data.Timestamp,
                VehicleId = data.VehicleId,
                Latitude = data.Latitude,
                Longitude = data.Longitude,
                Speed = data.Speed,
                IsMoving = data.IsMoving
            };

            if (data.IsMoving)
            {
                DistanceTraveled += data.Speed * (data.Timestamp - PreviousState.Timestamp).TotalHours * 3.6; // Convert speed to distance
            }
        }
    }
}
```

### 3. Module 2: Route Optimization Engine

```csharp
// Modules/RouteOptimizer/RouteOptimizer.cs
using System.Collections.Concurrent;
using System.Threading.Channels;

public class RouteOptimizationEngine : IDisposable
{
    private readonly Channel<RouteRequest> _routeRequests;
    private readonly ConcurrentDictionary<string, RoutePlan> _activeRoutes;
    private readonly ConcurrentDictionary<string, double> _trafficWeights;
    private readonly ILogger<RouteOptimizationEngine> _logger;
    private readonly CancellationTokenSource _cts = new();

    public RouteOptimizationEngine(
        Channel<RouteRequest> routeRequests,
        ILogger<RouteOptimizationEngine> logger)
    {
        _routeRequests = routeRequests;
        _activeRoutes = new ConcurrentDictionary<string, RoutePlan>();
        _trafficWeights = new ConcurrentDictionary<string, double>();
        _logger = logger;
    }

    public async Task StartOptimizationAsync()
    {
        await foreach (var request in _routeRequests.Reader.ReadAllAsync(_cts.Token))
        {
            try
            {
                var routePlan = await CalculateOptimalRoute(request);
                _activeRoutes.TryAdd(request.VehicleId, routePlan);
                _logger.LogInformation("Generated route for vehicle {VehicleId} with {SegmentCount} segments",
                    request.VehicleId, routePlan.Segments.Count);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error calculating route for vehicle {VehicleId}", request.VehicleId);
            }
        }
    }

    public async Task<RoutePlan> CalculateOptimalRoute(RouteRequest request)
    {
        // In a real implementation, this would use a proper graph database
        // and Dijkstra's algorithm with dynamic traffic weights

        // Simplified example with mock data
        var segments = new List<RouteSegment>();

        // Add some mock segments
        for (int i = 0; i < 5; i++)
        {
            var segment = new RouteSegment
            {
                Id = $"{request.VehicleId}-segment-{i}",
                StartLocation = $"Location {i}",
                EndLocation = $"Location {i + 1}",
                Distance = 5 + (new Random().NextDouble() * 5), // Random distance between 5-10km
                BaseCost = 1.5 + (new Random().NextDouble() * 2), // Random base cost
                TrafficWeight = _trafficWeights.GetOrDefault($"{request.VehicleId}-{i}", 1.0),
                LastUpdated = DateTime.UtcNow
            };
            segments.Add(segment);
        }

        var totalDistance = segments.Sum(s => s.Distance);
        var totalCost = segments.Sum(s => s.BaseCost * s.TrafficWeight);

        return new RoutePlan
        {
            VehicleId = request.VehicleId,
            Segments = segments,
            GeneratedAt = DateTime.UtcNow,
            TotalDistance = totalDistance,
            TotalEstimatedCost = totalCost
        };
    }

    public async Task UpdateTrafficConditions(string vehicleId, double latitude, double longitude,
        double weightFactor, int durationMinutes = 30)
    {
        // In a real system, we would update traffic weights based on actual traffic data
        // and location

        // For this example, we'll just apply the weight factor to nearby segments
        var affectedSegments = _activeRoutes
            .Where(r => r.Value.Segments.Any(s =>
                IsLocationNear(s.StartLocation, latitude, longitude) ||
                IsLocationNear(s.EndLocation, latitude, longitude)))
            .SelectMany(r => r.Value.Segments)
            .ToList();

        foreach (var segment in affectedSegments)
        {
            var currentWeight = _trafficWeights.GetOrDefault(segment.Id, 1.0);
            _trafficWeights.AddOrUpdate(segment.Id, currentWeight * weightFactor,
                (key, oldValue) => oldValue * weightFactor);

            // Update the segment in active routes
            foreach (var route in _activeRoutes.Values)
            {
                var existingSegment = route.Segments.FirstOrDefault(s => s.Id == segment.Id);
                if (existingSegment != null)
                {
                    existingSegment.TrafficWeight = _trafficWeights[segment.Id];
                    existingSegment.LastUpdated = DateTime.UtcNow;
                }
            }
        }

        // Schedule cleanup of traffic weights after duration
        _ = Task.Run(async () =>
        {
            await Task.Delay(durationMinutes * 60 * 1000);
            _trafficWeights.TryRemove(segment.Id, out _);
        });
    }

    private bool IsLocationNear(string location, double latitude, double longitude)
    {
        // Simplified location check - in reality would use proper distance calculation
        return location.Contains(latitude.ToString("0.00"));
    }

    public RoutePlan GetCurrentRoute(string vehicleId)
    {
        _activeRoutes.TryGetValue(vehicleId, out var route);
        return route;
    }

    public void Dispose()
    {
        _cts.Cancel();
        _routeRequests.Reader.Complete();
    }
}

