### 4. Module 3: Automated Billing & Invoicing Subsystem

```csharp
// Modules/BillingService/BillingService.cs
using System.Collections.Concurrent;

public class BillingService : IDisposable
{
    private readonly Channel<BillingEvent> _billingEvents;
    private readonly ConcurrentDictionary<string, VehicleBilling> _vehicleBilling;
    private readonly ILogger<BillingService> _logger;
    private readonly CancellationTokenSource _cts = new();

    public BillingService(
        Channel<BillingEvent> billingEvents,
        ILogger<BillingService> logger)
    {
        _billingEvents = billingEvents;
        _vehicleBilling = new ConcurrentDictionary<string, VehicleBilling>();
        _logger = logger;
    }

    public async Task StartBillingAsync()
    {
        await foreach (var eventData in _billingEvents.Reader.ReadAllAsync(_cts.Token))
        {
            try
            {
                ProcessBillingEvent(eventData);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing billing event for vehicle {VehicleId}", eventData.VehicleId);
            }
        }
    }

    private void ProcessBillingEvent(BillingEvent eventData)
    {
        var billing = _vehicleBilling.GetOrAdd(eventData.VehicleId, _ => new VehicleBilling());

        // Calculate toll based on distance and time
        double toll = CalculateToll(eventData);

        billing.AddEvent(eventData);
        billing.TotalAmount += toll;

        _logger.LogInformation("Processed billing event for vehicle {VehicleId}: {Toll} at {Location}",
            eventData.VehicleId, toll, eventData.Location);

        // Generate invoice periodically (simplified)
        if (billing.Events.Count % 10 == 0)
        {
            GenerateInvoice(billing);
        }
    }

    private double CalculateToll(BillingEvent eventData)
    {
        // Simple toll calculation - in reality would be more complex
        // Base toll per km + time-based component
        return eventData.DistanceTraveled * 1.2 +
               (eventData.ExitTime - eventData.EntryTime).TotalMinutes * 0.05;
    }

    public void ProcessCompletedRoute(RoutePlan routePlan)
    {
        var billing = _vehicleBilling.GetOrAdd(routePlan.VehicleId, _ => new VehicleBilling());

        foreach (var segment in routePlan.Segments)
        {
            // For each segment, create a billing event
            var eventData = new BillingEvent
            {
                VehicleId = routePlan.VehicleId,
                RouteSegmentId = segment.Id,
                EntryTime = DateTime.UtcNow.AddMinutes(-10), // Simulated entry
                ExitTime = DateTime.UtcNow,
                DistanceTraveled = segment.Distance,
                TollAmount = segment.BaseCost * segment.TrafficWeight,
                Location = $"{segment.StartLocation} to {segment.EndLocation}"
            };

            ProcessBillingEvent(eventData);
        }

        GenerateInvoice(billing);
    }

    private void GenerateInvoice(VehicleBilling billing)
    {
        _logger.LogInformation("Generating invoice for vehicle {VehicleId} with {EventCount} events",
            billing.VehicleId, billing.Events.Count);

        // In a real system, this would:
        // 1. Generate a PDF/HTML invoice
        // 2. Send it to the customer
        // 3. Update the database
        // 4. Send notifications
    }

    public VehicleBilling GetVehicleBilling(string vehicleId)
    {
        _vehicleBilling.TryGetValue(vehicleId, out var billing);
        return billing;
    }

    public void Dispose()
    {
        _cts.Cancel();
        _billingEvents.Reader.Complete();
    }

    private class VehicleBilling
    {
        public string VehicleId { get; set; }
        public List<BillingEvent> Events { get; } = new();
        public double TotalAmount { get; set; }
        public DateTime LastInvoiceDate { get; set; } = DateTime.MinValue;

        public void AddEvent(BillingEvent eventData)
        {
            Events.Add(eventData);
        }
    }
}
