### 5. Main Application and Data Flow Coordination

```csharp
// Program.cs
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

class Program
{
    static async Task Main(string[] args)
    {
        var host = Host.CreateDefaultBuilder(args)
            .ConfigureServices((hostContext, services) =>
            {
                // Configure channels for inter-module communication
                var telemetryChannel = Channel.CreateUnbounded<TelemetryData>();
                var routeRequests = Channel.CreateUnbounded<RouteRequest>();
                var billingEvents = Channel.CreateUnbounded<BillingEvent>();

                services.AddSingleton(telemetryChannel.Writer);
                services.AddSingleton(routeRequests.Writer);
                services.AddSingleton(billingEvents.Writer);

                services.AddSingleton<ChannelReader<TelemetryData>>(telemetryChannel.Reader);
                services.AddSingleton<ChannelReader<RouteRequest>>(routeRequests.Reader);
                services.AddSingleton<ChannelReader<BillingEvent>>(billingEvents.Reader);

                // Register services
                services.AddSingleton<FleetTracker>();
                services.AddSingleton<RouteOptimizationEngine>();
                services.AddSingleton<BillingService>();

                services.AddHostedService<Worker>();
            })
            .ConfigureLogging(logging =>
            {
                logging.ClearProviders();
                logging.AddConsole();
            })
            .Build();

        await host.RunAsync();
    }
}

public class Worker : BackgroundService
{
    private readonly FleetTracker _fleetTracker;
    private readonly RouteOptimizationEngine _routeOptimizer;
    private readonly BillingService _billingService;
    private readonly ChannelWriter<TelemetryData> _telemetryWriter;
    private readonly ChannelWriter<RouteRequest> _routeRequestsWriter;
    private readonly ILogger<Worker> _logger;

    public Worker(
        FleetTracker fleetTracker,
        RouteOptimizationEngine routeOptimizer,
        BillingService billingService,
        ChannelWriter<TelemetryData> telemetryWriter,
        ChannelWriter<RouteRequest> routeRequestsWriter,
        ILogger<Worker> logger)
    {
        _fleetTracker = fleetTracker;
        _routeOptimizer = routeOptimizer;
        _billingService = billingService;
        _telemetryWriter = telemetryWriter;
        _routeRequestsWriter = routeRequestsWriter;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        // Start all modules
        var trackerTask = Task.Run(() => _fleetTracker.StartTrackingAsync(), stoppingToken);
        var optimizerTask = Task.Run(() => _routeOptimizer.StartOptimizationAsync(), stoppingToken);
        var billingTask = Task.Run(() => _billingService.StartBillingAsync(), stoppingToken);

        // Simulate receiving telemetry data
        await SimulateTelemetryData(stoppingToken);

        // Wait for all tasks to complete
        await Task.WhenAll(trackerTask, optimizerTask, billingTask);
    }

    private async Task SimulateTelemetryData(CancellationToken stoppingToken)
    {
        var random = new Random();
        var vehicleIds = new[] { "VEH-001", "VEH-002", "VEH-003" };

        // Simulate initial route requests
        foreach (var vehicleId in vehicleIds)
        {
            var request = new RouteRequest
            {
                VehicleId = vehicleId,
                StartLocation = "Warehouse A",
                Destination = "Customer B"
            };
            await _routeRequestsWriter.WriteAsync(request, stoppingToken);
        }

        // Simulate telemetry data
        while (!stoppingToken.IsCancellationRequested)
        {
            foreach (var vehicleId in vehicleIds)
            {
                var telemetry = new TelemetryData
                {
                    VehicleId = vehicleId,
                    Timestamp = DateTime.UtcNow,
                    Latitude = 40.7 + random.NextDouble() * 0.1, // Simulated location
                    Longitude = -74.0 + random.NextDouble() * 0.1,
                    Speed = random.NextDouble() * 100, // Random speed
                    IsMoving = random.NextDouble() > 0.3 // 70% chance of moving
                };

                await _telemetryWriter.WriteAsync(telemetry, stoppingToken);

                // Occasionally generate a new route request
                if (random.NextDouble() < 0.05)
                {
                    var request = new RouteRequest
                    {
                        VehicleId = vehicleId,
                        StartLocation = "Location " + random.Next(1, 10),
                        Destination = "Location " + random.Next(1, 10)
                    };
                    await _routeRequestsWriter.WriteAsync(request, stoppingToken);
                }
            }

            await Task.Delay(1000, stoppingToken);
        }
    }
}
